CREATE OR REPLACE FUNCTION set_instance_status_updated_date()
RETURNS trigger
AS $function$
  BEGIN
    IF (OLD.jsonb->'statusId' IS DISTINCT FROM NEW.jsonb->'statusId') THEN
      -- Date time in "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'" format at UTC (00:00) time zone
      NEW.jsonb = jsonb_set(
        NEW.jsonb, '{statusUpdatedDate}',
        to_jsonb(to_char(CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.ms"Z"'))
      );
    END IF;
    RETURN NEW;
  END;
$function$  LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS set_instance_status_updated_date ON instance;

CREATE TRIGGER set_instance_status_updated_date BEFORE
UPDATE ON instance
FOR EACH ROW EXECUTE PROCEDURE set_instance_status_updated_date();

CREATE OR REPLACE FUNCTION set_instance_sourceRecordFormat()
  RETURNS TRIGGER AS $$
  BEGIN
    CASE TG_OP
    WHEN 'INSERT' THEN
      NEW.jsonb := NEW.jsonb - 'sourceRecordFormat';
    ELSE
      NEW.jsonb := CASE (SELECT count(*) FROM instance_source_marc WHERE id=NEW.id)
                   WHEN 0 THEN NEW.jsonb - 'sourceRecordFormat'
                   ELSE jsonb_set(NEW.jsonb, '{sourceRecordFormat}', '"MARC-JSON"')
                   END;
    END CASE;
    RETURN NEW;
  END;
  $$ language 'plpgsql';
DROP TRIGGER IF EXISTS set_instance_sourceRecordFormat ON instance CASCADE;
CREATE TRIGGER set_instance_sourceRecordFormat
  BEFORE INSERT OR UPDATE ON instance
  FOR EACH ROW EXECUTE PROCEDURE set_instance_sourceRecordFormat();

CREATE OR REPLACE FUNCTION update_instance_source_marc()
  RETURNS TRIGGER AS $$
  BEGIN
    IF (TG_OP = 'DELETE') THEN
      UPDATE instance
        SET jsonb = jsonb - 'sourceRecordFormat'
        WHERE id = OLD.id;
    ELSE
      UPDATE instance
        SET jsonb = jsonb_set(jsonb, '{sourceRecordFormat}', '"MARC-JSON"')
        WHERE id = NEW.id;
    END IF;
    RETURN NULL;
  END;
  $$ language 'plpgsql';
DROP TRIGGER IF EXISTS update_instance_source_marc ON instance_source_marc CASCADE;
CREATE TRIGGER update_instance_source_marc
  AFTER DELETE OR INSERT OR UPDATE ON instance_source_marc
  FOR EACH ROW EXECUTE PROCEDURE update_instance_source_marc();

CREATE OR REPLACE FUNCTION update_item_status_date() RETURNS TRIGGER
AS $$
  DECLARE
    newStatus text;
  BEGIN
    newStatus = NEW.jsonb->'status'->>'name';
    IF (newStatus IS DISTINCT FROM OLD.jsonb->'status'->>'name') THEN
      -- Date time in "YYYY-MM-DD"T"HH24:MI:SS.ms'Z'" format at UTC (00:00) time zone
      NEW.jsonb = jsonb_set(NEW.jsonb, '{status,date}',
       to_jsonb(to_char(CURRENT_TIMESTAMP(3) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.ms"Z"')), true);
    ELSIF (OLD.jsonb->'status'->'date' IS NOT NULL) THEN
      NEW.jsonb = jsonb_set(NEW.jsonb, '{status,date}', OLD.jsonb->'status'->'date', true);
    ELSE
      NEW.jsonb = NEW.jsonb #- '{status, date}';
    END IF;
    RETURN NEW;
  END;
  $$ LANGUAGE 'plpgsql';

DROP TRIGGER IF EXISTS update_item_status_date ON item;
CREATE TRIGGER update_item_status_date BEFORE UPDATE
ON item FOR EACH ROW EXECUTE PROCEDURE update_item_status_date();

CREATE SEQUENCE IF NOT EXISTS hrid_instances_seq
  INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 99999999999
  OWNED BY hrid_settings.jsonb;
CREATE SEQUENCE IF NOT EXISTS hrid_holdings_seq
  INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 99999999999
  OWNED BY hrid_settings.jsonb;
CREATE SEQUENCE IF NOT EXISTS hrid_items_seq
  INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 99999999999
  OWNED BY hrid_settings.jsonb;

GRANT ALL ON SEQUENCE hrid_instances_seq TO ${database.defaultSchemaName};
GRANT ALL ON SEQUENCE hrid_holdings_seq TO ${database.defaultSchemaName};
GRANT ALL ON SEQUENCE hrid_items_seq TO ${database.defaultSchemaName};
GRANT ALL ON TABLE hrid_settings TO ${database.defaultSchemaName};

ALTER TABLE preceding_succeeding_title
  DROP CONSTRAINT IF EXISTS preceding_or_succeeding_id_is_set;
ALTER TABLE preceding_succeeding_title
  ADD CONSTRAINT preceding_or_succeeding_id_is_set CHECK(
  jsonb->'precedingInstanceId' IS NOT NULL OR jsonb->'succeedingInstanceId' IS NOT NULL);
